/**
 * 候选图片预处理节点 (v2.0)
 * 根据FR-03要求对Pexels API返回的图片进行预处理
 */

// 可配置参数
const MIN_WIDTH = 1200; // 最小宽度要求
const PER_PAGE = 8; // 每页结果数

/**
 * 筛选符合条件的图片并提取URL列表
 * @param {Array} photos - Pexels API返回的图片数组
 * @returns {Object} 包含筛选后的图片数组和URL列表
 */
function preprocessPhotos(photos) {
  // FR-03.1: 过滤掉宽度小于1200px的图片
  const filteredPhotos = photos.filter(photo => {
    return photo.width >= MIN_WIDTH && photo.src && photo.src.original;
  });

  // FR-03.2: 提取候选图片URL列表
  const candidateUrls = filteredPhotos.map(photo => photo.src.original);

  return {
    filteredPhotos,
    candidateUrls,
    originalPhotos: photos
  };
}

// 主处理逻辑
try {
  const inputData = $input.all();

  // 检查是否有输入数据
  if (!inputData || inputData.length === 0) {
    return [{
      json: {
        error: "No input data received.",
        candidateUrls: [],
        filteredPhotos: [],
        originalPhotos: [],
        originalInput: null
      }
    }];
  }

  const firstInput = inputData[0];
  const apiResponse = firstInput.json;

  // 保存原始输入数据（包含articleTitle）
  const originalInput = $('Start').first().json;

  // 检查API响应格式
  if (!apiResponse || !apiResponse.photos) {
    return [{
      json: {
        error: "Invalid API response format.",
        candidateUrls: [],
        filteredPhotos: [],
        originalPhotos: [],
        originalInput
      }
    }];
  }

  const photos = apiResponse.photos;

  // 执行图片预处理
  const result = preprocessPhotos(photos);

  // FR-03.3: 检查是否有候选图片
  if (result.candidateUrls.length === 0) {
    return [{
      json: {
        error: "No suitable images found after filtering.",
        candidateUrls: [],
        filteredPhotos: [],
        originalPhotos: photos,
        originalInput
      }
    }];
  }

  // 返回预处理结果
  return [{
    json: {
      error: null,
      candidateUrls: result.candidateUrls,
      filteredPhotos: result.filteredPhotos,
      originalPhotos: result.originalPhotos,
      originalInput
    }
  }];

} catch (error) {
  // 处理意外错误
  return [{
    json: {
      error: `Processing error: ${error.message}`,
      candidateUrls: [],
      filteredPhotos: [],
      originalPhotos: [],
      originalInput: null
    }
  }];
}

/**
 * Pexels API错误处理节点
 * 处理Pexels API请求失败的情况
 */

// 获取错误信息
const errorData = $input.all()[0];
const error = errorData.error;

let errorMessage = "Unknown error occurred.";

// 根据HTTP状态码确定错误类型
if (error && error.httpCode) {
  switch (error.httpCode) {
    case 401:
      // EH-01: API认证失败
      errorMessage = "API authentication failed. Please check your Pexels API credentials.";
      break;
    case 429:
      errorMessage = "API rate limit exceeded. Please try again later.";
      break;
    case 500:
    case 502:
    case 503:
    case 504:
      // EH-03: API服务不可用
      errorMessage = "Pexels API service is currently unavailable. Please try again later.";
      break;
    default:
      errorMessage = `API request failed with status ${error.httpCode}: ${error.message || 'Unknown error'}`;
  }
} else if (error && error.message) {
  errorMessage = error.message;
}

// 返回错误格式的输出
return [{
  json: {
    imageUrl: null,
    altText: null,
    photographer: null,
    photographerUrl: null,
    error: errorMessage
  }
}];

// 1. 获取上一个AI节点返回的完整数据对象
const aiOutput = $input.item.json;

// --- 智能路径判断 ---
// 这个变量用来存放我们最终要解析的字符串
let markdownString;

// 2. 检查是否存在复杂的 response.generations 路径
if (aiOutput.response && aiOutput.response.generations && aiOutput.response.generations.length > 0) {
  // 如果是复杂结构，就按复杂路径去取值
  console.log("检测到复杂输出格式，正在按复杂路径解析...");
  markdownString = aiOutput.response.generations[0][0].text;
} 
// 3. 如果复杂路径不存在，再检查是否存在简单的 .text 路径
else if (aiOutput.text) {
  // 如果是简单结构，就直接从 .text 取值
  console.log("检测到简单输出格式，正在按简单路径解析...");
  markdownString = aiOutput.text;
} 
// 4. 如果两种格式都不是，就抛出错误，防止流程继续
else {
  throw new Error("无法识别的AI输出格式，既没有找到 .text 也没有找到 .response.generations");
}

// --- 后续处理代码保持不变 ---

// 5. 清理 AI 返回的文本中可能包含的Markdown格式
const cleanJsonString = markdownString.replace(/```json\n|```/g, '');

// 6. 解析干净的JSON字符串
const aiDecision = JSON.parse(cleanJsonString);

// 7. 提取我们需要的索引号
const bestImageIndex = aiDecision.bestImageIndex;

// 8. 返回一个干净的、只包含索引号的输出
return {
  json: {
    bestImageIndex: bestImageIndex
  }
};
